&lt;p data-start=&quot;0&quot; data-end=&quot;18&quot;&gt;&lt;strong data-start=&quot;0&quot; data-end=&quot;18&quot;&gt;Deine Aufgaben&lt;/strong&gt;&lt;/p&gt;
&lt;ul data-start=&quot;20&quot; data-end=&quot;1235&quot;&gt;
&lt;li data-section-id=&quot;f9n8fs&quot; data-start=&quot;20&quot; data-end=&quot;188&quot;&gt;Definition elektrischer Anforderungen für Energiefluss-, Schutz- und Überwachungskomponenten innerhalb unserer Batterieenergiespeicher- und Leistungselektroniksysteme&lt;/li&gt;
&lt;li data-section-id=&quot;1i6zm2z&quot; data-start=&quot;189&quot; data-end=&quot;431&quot;&gt;Ableitung technischer Anforderungen aus Kundenspezifikationen, Projektvorgaben, Risikoanalysen sowie relevanten IEC-, EN- und VDE-Normen unter Berücksichtigung mechanischer, thermischer, softwareseitiger und systemintegrativer Anforderungen&lt;/li&gt;
&lt;li data-section-id=&quot;1p5znfz&quot; data-start=&quot;432&quot; data-end=&quot;658&quot;&gt;Durchführung elektrischer Berechnungen und Analysen, einschließlich Kabel- und Stromschienenauslegung, Kurzschlussverhalten, Spannungsabfall, thermischer Belastung, Schutzkoordination, Isolationskonzepten und Fehlerszenarien&lt;/li&gt;
&lt;li data-section-id=&quot;18nk74i&quot; data-start=&quot;659&quot; data-end=&quot;849&quot;&gt;Entwicklung und Mitgestaltung elektrischer Systemarchitekturen für Hoch- und Niederspannungsverteilung, Kommunikationsschnittstellen, Schutzkonzepte, Fehlerbehandlung und Systemintegration&lt;/li&gt;
&lt;li data-section-id=&quot;bbmvum&quot; data-start=&quot;850&quot; data-end=&quot;1033&quot;&gt;Definition von Prüf- und Validierungsanforderungen, Abnahmekriterien und Konformitätsdokumentationen sowie Unterstützung bei FAT-, SAT-, Zertifizierungs- und Kundenfreigabeprozessen&lt;/li&gt;
&lt;li data-section-id=&quot;b8aq2c&quot; data-start=&quot;1034&quot; data-end=&quot;1235&quot;&gt;Begleitung von Kundenprojekten über den gesamten Lebenszyklus hinweg, Teilnahme an Design Reviews, FMEAs, Risiko- und Gefährdungsanalysen sowie Koordination von elektrischen Tests und Inbetriebnahmen&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-start=&quot;1237&quot; data-end=&quot;1252&quot;&gt;&lt;strong data-start=&quot;1237&quot; data-end=&quot;1252&quot;&gt;Dein Profil&lt;/strong&gt;&lt;/p&gt;
&lt;ul data-start=&quot;1254&quot; data-end=&quot;2498&quot; data-is-last-node=&quot;&quot; data-is-only-node=&quot;&quot;&gt;
&lt;li data-section-id=&quot;1xsittu&quot; data-start=&quot;1254&quot; data-end=&quot;1374&quot;&gt;Abgeschlossenes Studium der Elektrotechnik, Energietechnik, Leistungselektronik oder einer vergleichbaren Fachrichtung&lt;/li&gt;
&lt;li data-section-id=&quot;yh4uqx&quot; data-start=&quot;1375&quot; data-end=&quot;1591&quot;&gt;Mehrjährige Berufserfahrung in Hochspannungsanlagen, industriellen Energiesystemen, Maschinenbau, Energiespeichern, Leistungselektronik, E-Mobilität, Luft- und Raumfahrt oder vergleichbaren Hochleistungsanwendungen&lt;/li&gt;
&lt;li data-section-id=&quot;1wnrqyd&quot; data-start=&quot;1592&quot; data-end=&quot;1849&quot;&gt;Fundierte Kenntnisse relevanter IEC-, EN- und VDE-Normen (z. B. VDE 0113-1, VDE 0100-410 und VDE 0660-600-1) sowie tiefgehende Expertise in Hochspannungsdesign, Schutzkonzepten, Erdung, Isolationsüberwachung, Kurzschlussverhalten und thermischer Auslegung&lt;/li&gt;
&lt;li data-section-id=&quot;spvzhs&quot; data-start=&quot;1850&quot; data-end=&quot;2025&quot;&gt;Erfahrung in der Definition und Bewertung technischer Anforderungen, elektrischer Architekturen, Komponentenspezifikationen, Validierungspläne und Nachweise zur Verifikation&lt;/li&gt;
&lt;li data-section-id=&quot;4ru4ce&quot; data-start=&quot;2026&quot; data-end=&quot;2318&quot;&gt;Nachgewiesene Fähigkeit zur erfolgreichen Zusammenarbeit in interdisziplinären Teams aus Engineering, Produktentwicklung, Einkauf, Produktion und Kundenprojektorganisationen, idealerweise mit Erfahrung im Bereich Batterieenergiespeichersysteme oder netzgekoppelte Leistungselektroniksysteme&lt;/li&gt;
&lt;li data-section-id=&quot;g3zbk3&quot; data-start=&quot;2319&quot; data-end=&quot;2498&quot; data-is-last-node=&quot;&quot;&gt;Verhandlungssichere Deutsch- und Englischkenntnisse; Erfahrung mit Automatisierung, Skripting oder KI-gestützten Tools zur Optimierung technischer Arbeitsabläufe ist von Vorteil&lt;/li&gt;
&lt;/ul&gt;
